package local.chatagent.privatechat;
import android.content.*;import android.graphics.*;import android.graphics.drawable.GradientDrawable;import android.util.Base64;import android.view.*;import android.widget.*;import org.json.*;
final class ProfileData {
 static JSONObject read(LocalStore store,String id){try{JSONObject all=new JSONObject(store.readMeta("profiles","{}"));JSONObject p=all.optJSONObject(id);if(p!=null)return p;}catch(Exception ignored){}try{return new JSONObject().put("revision",0).put("nickname",id.equals("self")?"我":store.readMeta("chatName","小鲸鱼")).put("signature","").put("region","").put("avatar","");}catch(Exception e){throw new IllegalStateException(e);}}
 static void sync(Api api,LocalStore store,String epoch)throws Exception{String version=epoch.equals(store.readMeta("profilesEpoch",""))?store.readMeta("profilesVersion",""):"";JSONObject result=api.object("/v1/profiles?after="+SyncService.encode(version),null);if(!result.isNull("profiles"))store.meta("profiles",result.getJSONObject("profiles").toString());store.meta("profilesVersion",result.getString("version"));store.meta("profilesEpoch",epoch);}
 static void saved(LocalStore store,String id,JSONObject p)throws Exception{JSONObject all=new JSONObject(store.readMeta("profiles","{}"));all.put(id,p);store.meta("profiles",all.toString());store.meta("profilesVersion","");}
 static View avatar(Context context,JSONObject profile,boolean mine){FrameLayout frame=new FrameLayout(context);GradientDrawable bg=new GradientDrawable();bg.setColor(mine?0xffdfebff:0xff659bea);bg.setCornerRadius(4*context.getResources().getDisplayMetrics().density);frame.setBackground(bg);frame.setClipToOutline(true);String value=profile.optString("avatar");try{if(!value.isEmpty()){byte[] bytes=Base64.decode(value.substring(value.indexOf(',')+1),Base64.DEFAULT);Bitmap bitmap=BitmapFactory.decodeByteArray(bytes,0,bytes.length);if(bitmap!=null){ImageView image=new ImageView(context);image.setImageBitmap(bitmap);image.setScaleType(ImageView.ScaleType.CENTER_CROP);frame.addView(image,new FrameLayout.LayoutParams(-1,-1));return frame;}}}catch(Exception ignored){}TextView label=new TextView(context);label.setText(mine?"我":"鲸");label.setTextSize(16);label.setTextColor(mine?0xff527fbf:Color.WHITE);label.setGravity(Gravity.CENTER);frame.addView(label,new FrameLayout.LayoutParams(-1,-1));return frame;}
 static void open(Context context,String id){context.startActivity(new Intent(context,ProfileActivity.class).putExtra("person",id));}
}
